import { afterEach, describe, expect, it, vi } from 'vitest';
import { validateCouponCode } from '../../../task-a3-unit-tests/real/lib/coupons';

const coupon = {
  id: 'coupon-1', code: 'SAVE', name: 'Save', description: null,
  discount_type: 'fixed', discount_value: 1000, minimum_amount: 0, maximum_discount: null,
  usage_limit: null, usage_count: 0, user_usage_limit: 1, valid_from: null, valid_until: null,
  is_active: true, applies_to_product_id: null,
};

function fakeDb(data: any = coupon, usageCount = 0) {
  const couponQuery: any = {};
  couponQuery.select = vi.fn(() => couponQuery);
  couponQuery.eq = vi.fn(() => couponQuery);
  couponQuery.maybeSingle = vi.fn().mockResolvedValue({ data, error: null });
  let usageEqCount = 0;
  const usageQuery: any = {};
  usageQuery.select = vi.fn(() => usageQuery);
  usageQuery.eq = vi.fn(() => ++usageEqCount === 2 ? Promise.resolve({ count: usageCount, error: null }) : usageQuery);
  const from = vi.fn((table: string) => table === 'coupons' ? couponQuery : usageQuery);
  return { client: { from } as any, from };
}

async function apply(data: any, subtotal = 10000, usageCount = 0, items?: Array<{ productId: string; price: number; quantity: number }>) {
  const db = fakeDb(data, usageCount);
  return { result: await validateCouponCode({ supabase: db.client, code: 'SAVE', subtotal, userId: 'user-1', items }), db };
}

afterEach(() => { vi.useRealTimers(); vi.restoreAllMocks(); });

describe('A-4 coupon acceptance flow', () => {
  it.each([
    [{ ...coupon, discount_type: 'percentage', discount_value: 20 }, 2000, 8000],
    [{ ...coupon, discount_type: 'fixed', discount_value: 1500 }, 1500, 8500],
  ])('shows the discount and final amount for valid coupons', async (data, discountAmount, finalAmount) => {
    const { result } = await apply(data);
    expect(result).toMatchObject({ discountAmount, finalAmount });
  });

  it.each([
    ['', 'user-1', { error: '쿠폰 코드를 입력해주세요.', status: 400 }],
    ['SAVE', '', { error: '로그인이 필요합니다.', status: 401 }],
  ])('rejects missing code or authentication before DB I/O', async (code, userId, expected) => {
    const from = vi.fn();
    await expect(validateCouponCode({ supabase: { from } as any, code, subtotal: 10000, userId })).resolves.toEqual(expected);
    expect(from).not.toHaveBeenCalled();
  });

  it('rejects nonexistent, expired, and exhausted coupons with exact reasons', async () => {
    expect((await apply(null)).result).toEqual({ error: '유효하지 않은 쿠폰 코드입니다.', status: 404 });
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-08-17T12:00:00+09:00'));
    expect((await apply({ ...coupon, valid_until: '2026-08-16' })).result).toEqual({ error: '만료된 쿠폰입니다.', status: 400 });
    expect((await apply({ ...coupon, user_usage_limit: 1 }, 10000, 1)).result).toEqual({ error: '이미 사용 한도를 채운 쿠폰입니다.', status: 400 });
  });

  it('accepts the exact minimum and rejects one won below using independent fakes', async () => {
    const equal = await apply({ ...coupon, minimum_amount: 10000 }, 10000);
    expect(equal.result).toMatchObject({ discountAmount: 1000, finalAmount: 9000 });
    const below = await apply({ ...coupon, minimum_amount: 10000 }, 9999);
    expect(below.result).toEqual({ error: '최소 주문 금액 10,000원 이상이어야 합니다.', status: 400 });
    expect(equal.db.client).not.toBe(below.db.client);
  });

  it('does not exceed maximum_discount', async () => {
    const { result } = await apply({ ...coupon, discount_type: 'percentage', discount_value: 50, maximum_discount: 2000 });
    expect(result).toMatchObject({ discountAmount: 2000, finalAmount: 8000 });
  });

  it('uses server-trusted item totals instead of the client subtotal', async () => {
    const items = [{ productId: 'P1', price: 6000, quantity: 2 }];
    const { result } = await apply({ ...coupon, discount_type: 'percentage', discount_value: 20 }, 999999, 0, items);
    expect(result).toMatchObject({ discountAmount: 2400, finalAmount: 9600 });
  });
});

import assert from 'node:assert/strict';
import { Given, Then, When, World, setWorldConstructor } from '@cucumber/cucumber';
import { validateCouponCode, type CouponValidationResult } from '../../../task-a3-unit-tests/real/lib/coupons';

const initialCoupon = () => ({
  id: 'coupon-1', code: 'SAVE', name: 'Save', description: null,
  discount_type: 'fixed' as const, discount_value: 1000, minimum_amount: 0, maximum_discount: null,
  usage_limit: null, usage_count: 0, user_usage_limit: 1, valid_from: null, valid_until: null,
  is_active: true, applies_to_product_id: null,
});

class CouponWorld extends World {
  userId = '';
  code = 'SAVE';
  subtotal = 10000;
  items: Array<{ productId: string; price: number; quantity: number }> | undefined;
  coupon: any = initialCoupon();
  usageCount = 0;
  fromCalls = 0;
  result: CouponValidationResult | undefined;

  newClient() {
    const couponQuery: any = {};
    couponQuery.select = () => couponQuery;
    couponQuery.eq = () => couponQuery;
    couponQuery.maybeSingle = async () => ({ data: this.coupon, error: null });
    let usageEqCount = 0;
    const usageQuery: any = {};
    usageQuery.select = () => usageQuery;
    usageQuery.eq = () => ++usageEqCount === 2 ? Promise.resolve({ count: this.usageCount, error: null }) : usageQuery;
    return {
      from: (table: string) => {
        this.fromCalls += 1;
        return table === 'coupons' ? couponQuery : usageQuery;
      },
    } as any;
  }
}

setWorldConstructor(CouponWorld);

Given('고객 {string}이 로그인했다', function (this: CouponWorld, userId: string) { this.userId = userId; });
Given('로그인하지 않은 고객이다', function (this: CouponWorld) { this.userId = ''; });
Given('쿠폰 코드는 {string}이다', function (this: CouponWorld, code: string) { this.code = code; });
Given('쿠폰 코드를 입력하지 않았다', function (this: CouponWorld) { this.code = ''; });
Given('주문 금액은 {int}원이다', function (this: CouponWorld, subtotal: number) { this.subtotal = subtotal; });
Given('클라이언트 subtotal은 {int}원이다', function (this: CouponWorld, subtotal: number) { this.subtotal = subtotal; });
Given('장바구니에는 {int}원 상품 {int}개가 있다', function (this: CouponWorld, price: number, quantity: number) { this.items = [{ productId: 'P1', price, quantity }]; });
Given('쿠폰은 {int}퍼센트 정률 할인이고 최소 주문금액은 {int}원이다', function (this: CouponWorld, value: number, minimum: number) { this.coupon = { ...this.coupon, discount_type: 'percentage', discount_value: value, minimum_amount: minimum }; });
Given('쿠폰은 {int}원 정액 할인이고 최소 주문금액은 {int}원이다', function (this: CouponWorld, value: number, minimum: number) { this.coupon = { ...this.coupon, discount_type: 'fixed', discount_value: value, minimum_amount: minimum }; });
Given('쿠폰은 {int}퍼센트 정률 할인이고 최대 할인 한도는 {int}원이다', function (this: CouponWorld, value: number, maximum: number) { this.coupon = { ...this.coupon, discount_type: 'percentage', discount_value: value, maximum_discount: maximum }; });
Given('쿠폰의 최소 주문금액은 {int}원이다', function (this: CouponWorld, minimum: number) { this.coupon = { ...this.coupon, minimum_amount: minimum }; });
Given('DB에 해당 쿠폰이 없다', function (this: CouponWorld) { this.coupon = null; });
Given('쿠폰 종료일은 {string}이다', function (this: CouponWorld, date: string) { this.coupon = { ...this.coupon, valid_until: date }; });
Given('쿠폰의 사용자 사용 한도는 {int}회이고 사용 횟수는 {int}회이다', function (this: CouponWorld, limit: number, count: number) { this.coupon = { ...this.coupon, user_usage_limit: limit }; this.usageCount = count; });

When('고객이 쿠폰을 적용하면', async function (this: CouponWorld) {
  this.result = await validateCouponCode({ supabase: this.newClient(), code: this.code, subtotal: this.subtotal, userId: this.userId, items: this.items });
});

Then('주문이 승인된다', function (this: CouponWorld) { assert.ok(this.result && !('error' in this.result)); });
Then('할인 금액은 {int}원이다', function (this: CouponWorld, amount: number) { assert.ok(this.result && 'discountAmount' in this.result); assert.equal(this.result.discountAmount, amount); });
Then('최종 결제 금액은 {int}원이다', function (this: CouponWorld, amount: number) { assert.ok(this.result && 'finalAmount' in this.result); assert.equal(this.result.finalAmount, amount); });
Then('상태는 {int}이다', function (this: CouponWorld, status: number) { assert.ok(this.result && 'status' in this.result); assert.equal(this.result.status, status); });
Then('실패 사유는 {string}이다', function (this: CouponWorld, error: string) { assert.ok(this.result && 'error' in this.result); assert.equal(this.result.error, error); });
Then('DB 조회 횟수는 {int}회이다', function (this: CouponWorld, count: number) { assert.equal(this.fromCalls, count); });
